type Event =
  | { kind: "order"; total: number }
  | { kind: "refund"; total: number }
  | { kind: "visit"; count: number };

function describe(event: Event): string {
  switch (event.kind) {
    case "order":
      return `order ${event.total}`;
    case "refund":
      return `refund ${event.total}`;
    case "visit":
      return `visit ${event.count}`;
    default: {
      const neverEvent: never = event;
      return neverEvent;
    }
  }
}
